<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require dirname(__DIR__,2).'/vendor/autoload.php';use App\Admin;use App\Security;
Admin::requirePermission('products.manage');$pdo=db();$id=(int)($_GET['id']??$_POST['product_id']??0);$q=$pdo->prepare("SELECT id,name FROM products WHERE id=?");$q->execute([$id]);$product=$q->fetch();if(!$product){http_response_code(404);exit('المنتج غير موجود.');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){Security::requireCsrf();try{$imageId=(int)($_POST['image_id']??0);$action=(string)($_POST['action']??'');$q=$pdo->prepare("SELECT * FROM product_images WHERE id=? AND product_id=?");$q->execute([$imageId,$id]);$img=$q->fetch();if(!$img)throw new RuntimeException('الصورة غير موجودة.');if($action==='primary'){$pdo->beginTransaction();$pdo->prepare("UPDATE product_images SET is_primary=0 WHERE product_id=?")->execute([$id]);$pdo->prepare("UPDATE product_images SET is_primary=1 WHERE id=?")->execute([$imageId]);$pdo->commit();}elseif($action==='delete'){$pdo->beginTransaction();$pdo->prepare("DELETE FROM product_images WHERE id=?")->execute([$imageId]);if((int)$img['is_primary']){$q=$pdo->prepare("SELECT id FROM product_images WHERE product_id=? ORDER BY sort_order,id LIMIT 1");$q->execute([$id]);$next=$q->fetchColumn();if($next)$pdo->prepare("UPDATE product_images SET is_primary=1 WHERE id=?")->execute([$next]);}$pdo->commit();$root=realpath(dirname(__DIR__).'/uploads/products');$file=realpath(dirname(__DIR__).'/'.$img['image_path']);if($root&&$file&&str_starts_with($file,$root.DIRECTORY_SEPARATOR)&&is_file($file))@unlink($file);}else throw new RuntimeException('إجراء غير معروف.');Admin::audit('product.image.'.$action,'product',$id,['image_id'=>$imageId]);header('Location: product-images.php?id='.$id.'&updated=1');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'تعذر تعديل الصور.';}}
$q=$pdo->prepare("SELECT * FROM product_images WHERE product_id=? ORDER BY is_primary DESC,sort_order,id");$q->execute([$id]);$images=$q->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>صور المنتج</title><link rel="stylesheet" href="../assets/css/store.css"><style>.wrap{max-width:1000px;margin:30px auto;padding:0 16px}.gallery{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.tile{border:1px solid #49371c;background:#111;border-radius:12px;padding:10px}.tile img{width:100%;height:160px;object-fit:contain;background:#090909}.tile form{margin-top:8px}.tile .btn{width:100%;margin-top:5px}@media(max-width:650px){.gallery{grid-template-columns:repeat(2,1fr)}}</style></head><body><main class="wrap"><a class="text-link" href="products.php">← المنتجات</a><h1>صور: <?=e($product['name'])?></h1><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['updated'])):?><div class="notice">تم تحديث معرض الصور.</div><?php endif;?><p>ارفع الصور من نموذج تعديل المنتج، ومن هنا يمكنك اختيار الصورة الرئيسية أو حذف صورة.</p><div class="gallery"><?php foreach($images as $img):?><article class="tile"><img src="../<?=e($img['image_path'])?>" alt="<?=e($img['alt_text']??$product['name'])?>"><?php if((int)$img['is_primary']):?><span class="available">الصورة الرئيسية</span><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><input type="hidden" name="product_id" value="<?=$id?>"><input type="hidden" name="image_id" value="<?=(int)$img['id']?>"><button class="btn btn-outline" name="action" value="primary">تعيين كرئيسية</button><button class="btn btn-outline" name="action" value="delete">حذف الصورة</button></form></article><?php endforeach;?></div><?php if(!$images):?><div class="empty-state">لا توجد صور لهذا المنتج.</div><?php endif;?></main></body></html>